// UsdGeomTetMesh — a tetrahedral mesh schema.
//
// Encodes a set of tetrahedra, each defined by 4 indices into the inherited
// `points` attribute. Provides surface-face extraction and inverted-element
// detection.
//
// Reference: pxr/usd/usdGeom/tetMesh.{h,cpp}



import type { Orientation } from './gprim.ts'
import { attrVal, asToken, plain } from './valueUtils.ts'

// The four triangle faces of a tetrahedron, expressed as index triples into the
// tet's int4. This CCW ordering yields outward-facing normals for a
// "rightHanded" tetrahedron. Mirrors tetFaceIndices / faceVerts in tetMesh.cpp.
const TET_FACE_INDICES: readonly [number, number, number][] = [
  [1, 2, 3],
  [0, 3, 2],
  [0, 1, 3],
  [0, 2, 1],
]


// ---- Pure algorithm helpers (ported from tetMesh.cpp) ----

// Sorts a triple ascending — the orientation-independent "signature" used to
// detect shared faces (two faces are shared iff their sorted triples match).
function sorted3(a: number, b: number, c: number): [number, number, number] {
  if (a > b) [a, b] = [b, a]
  if (a > c) [a, c] = [c, a]
  if (b > c) [b, c] = [c, b]
  return [a, b, c]
}

// Lexicographic comparison of oriented triangles (_Vec3iCmp).
function vec3iCmp(f1: number[], f2: number[]): number {
  if (f1[0]! !== f2[0]!) return f1[0]! - f2[0]!
  if (f1[1]! !== f2[1]!) return f1[1]! - f2[1]!
  return f1[2]! - f2[2]!
}

export function computeSurfaceFaces(tetVertexIndices: number[][]): number[][] {
  // Map the sorted-triple signature to its occurrence count and the oriented
  // triangle (so winding is preserved through the sort by signature).
  const sigToCountAndTriangle = new Map<
    string,
    { count: number; triangle: [number, number, number] }
  >()

  for (const tet of tetVertexIndices) {
    for (const face of TET_FACE_INDICES) {
      const triangle: [number, number, number] = [
        tet[face[0]]!,
        tet[face[1]]!,
        tet[face[2]]!,
      ]
      const sig = sorted3(triangle[0], triangle[1], triangle[2])
      const key = `${sig[0]},${sig[1]},${sig[2]}`
      const item = sigToCountAndTriangle.get(key)
      if (item) {
        item.count++
        item.triangle = triangle
      } else {
        sigToCountAndTriangle.set(key, { count: 1, triangle })
      }
    }
  }

  const result: number[][] = []
  for (const { count, triangle } of sigToCountAndTriangle.values()) {
    if (count === 1) result.push(triangle)
  }
  // Sort for deterministic output across runs.
  result.sort(vec3iCmp)
  return result
}

export function findInvertedElements(
  points: number[][],
  tetVertexIndices: number[][],
  orientation: Orientation,
): number[] {
  const invertedElements: number[] = []
  // For a non-inverted, rightHanded element all face normals point outward from
  // the element center, so sign(faceNormal · (center - faceV0)) is negative; the
  // leftHanded case flips the expected sign.
  const sign = orientation === 'leftHanded' ? 1 : -1

  for (let t = 0; t < tetVertexIndices.length; t++) {
    const tet = tetVertexIndices[t]!
    const elemPoints: [number, number, number][] = [
      points[tet[0]!]! as [number, number, number],
      points[tet[1]!]! as [number, number, number],
      points[tet[2]!]! as [number, number, number],
      points[tet[3]!]! as [number, number, number],
    ]

    const center: [number, number, number] = [0, 0, 0]
    for (const p of elemPoints) {
      center[0] += p[0]
      center[1] += p[1]
      center[2] += p[2]
    }
    center[0] *= 0.25
    center[1] *= 0.25
    center[2] *= 0.25

    for (const face of TET_FACE_INDICES) {
      const v0 = elemPoints[face[0]]!
      const v1 = elemPoints[face[1]]!
      const v2 = elemPoints[face[2]]!
      const normal = cross(sub(v1, v0), sub(v2, v0))
      if (sign * dot(normal, sub(center, v0)) < 0) {
        invertedElements.push(t)
        break
      }
    }
  }

  return invertedElements
}

// ---- Plain-tuple vector ops (GfCross / GfDot on number[3]) ----

function sub(a: number[], b: number[]): [number, number, number] {
  return [a[0]! - b[0]!, a[1]! - b[1]!, a[2]! - b[2]!]
}

function cross(a: number[], b: number[]): [number, number, number] {
  return [
    a[1]! * b[2]! - a[2]! * b[1]!,
    a[2]! * b[0]! - a[0]! * b[2]!,
    a[0]! * b[1]! - a[1]! * b[0]!,
  ]
}

function dot(a: number[], b: number[]): number {
  return a[0]! * b[0]! + a[1]! * b[1]! + a[2]! * b[2]!
}

// ---- Value coercion ----

// Normalize an int4[]/int3[]/point3f[] value (number[][]) for the algorithms.
// USDC/in-memory both surface vec arrays as number[][]; tolerate null/scalar.
function toVecArray(v: unknown): number[][] {
  v = plain(v)
  if (!Array.isArray(v)) return []
  return v.map((el) => (Array.isArray(el) ? (el as number[]).map(Number) : [Number(el)]))
}

// Resolve a readable Prim (with getAttr) from the authoring schema handle.
function readPrim(tetMesh: TetMesh): Prim | undefined {
  return tetMesh.stage.getPrim(tetMesh.path)
}
